// The ANSI derivation (cert record decision 1). Anchors are the QR tokens,
// pure white and pure black in every mode; anything else fails the check.
const ANCHOR_WHITE = 'colour.qr-field'
const ANCHOR_BLACK = 'colour.qr-module'
const ANSI_HUES = {
  red: 'colour.danger',
  green: 'colour.success',
  yellow: 'colour.warning',
  blue: 'colour.info',
  magenta: 'colour.syntax-keyword',
}
const BRIGHT_MIX = 0.3
const CYAN_MIX = 0.5
const BRIGHT_BLACK_TOKEN = 'colour.muted'

// Portal encodings TH reads (D91.18, research §8). color-scheme is the
// xdg-desktop-portal encoding; contrast is our own extension, served by PT's
// portal; the override is desktop.json's appearance value, written by ST.
export const PORTAL_SCHEME = { noPreference: 0, preferDark: 1, preferLight: 2 }
export const PORTAL_CONTRAST = { normal: 0, high: 1 }
export const APPEARANCE_OVERRIDES = ['system', 'light', 'dark', 'hc-light', 'hc-dark']

