// The consumed slice of consumers.json: version 1, every mode, each entry's
// type, resolved DTCG value, CSS and variable. Values are narrowed per type
// at use, with errors naming the token and mode.
const consumerEntry = z
  .object({ type: z.string(), value: z.unknown(), css: z.string(), variable: z.string() })
  .strict()
const consumersSchema = z
  .object({
    version: z.literal(DESKTOP_CONSUMER_VERSION),
    modes: z.record(z.string(), z.record(z.string(), consumerEntry)),
    hostRoles: z.unknown(),
    contrastPairs: z.unknown(),
  })
  .strict()

export function parseConsumers(input) {
  const parsed = consumersSchema.parse(input)
  for (const mode of DESKTOP_MODES) {
    if (parsed.modes[mode] === undefined) throw new Error(`Token consumer file lacks mode: ${mode}`)
  }
  return parsed
}

const colourValue = z
  .object({
    colorSpace: z.enum(['srgb', 'oklch']),
    components: z.tuple([z.number(), z.number(), z.number()]),
    alpha: z.number().min(0).max(1),
  })
  .strict()

function entryAt(consumers, mode, name) {
  const entry = consumers.modes[mode][name]
  if (entry === undefined) throw new Error(`Unknown token in ${mode}: ${name}`)
  return entry
}

export function colourAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'color') throw new Error(`Not a colour token: ${name}`)
  return colourValue.parse(entry.value)
}

function dimensionAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'dimension') throw new Error(`Not a dimension token: ${name}`)
  return z.object({ value: z.number(), unit: z.string() }).strict().parse(entry.value)
}

function durationMsAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'duration') throw new Error(`Not a duration token: ${name}`)
  const parsed = z
    .object({ value: z.number().nonnegative(), unit: z.enum(['ms', 's']) })
    .strict()
    .parse(entry.value)
  return parsed.unit === 's' ? parsed.value * 1000 : parsed.value
}

function numberAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'number' && entry.type !== 'fontWeight')
    throw new Error(`Not a number token: ${name}`)
  return z.number().parse(entry.value)
}

function bezierAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'cubicBezier') throw new Error(`Not a curve token: ${name}`)
  return z.tuple([z.number(), z.number(), z.number(), z.number()]).parse(entry.value)
}

function familyAt(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'fontFamily') throw new Error(`Not a font family token: ${name}`)
  return z.array(z.string().min(1)).min(1).parse(entry.value)
}

// 8-bit sRGB emission, rounded exactly as M114's generator does, so desktop
// bytes agree with muse.css where they carry the same colour.
function srgbBytes(colour) {
  return [...colour.components, ...(colour.alpha === 1 ? [] : [colour.alpha])].map((n) =>
    Math.round(n * 255),
  )
}

export function hexOf(colour) {
  return `#${srgbBytes(colour)
    .map((n) => n.toString(16).padStart(2, '0'))
    .join('')}`
}

// CSS Color 4's OKLab -> linear sRGB -> encoded sRGB conversion, the same
// algorithm M114's check uses; the desktop's only OKLCH colours are the
// decorative status ramp, which still needs a concrete value everywhere.
export function oklchToSrgb(colour) {
  if (colour.colorSpace === 'srgb') return colour
  const [l, chroma, hue] = colour.components
  const radians = (hue * Math.PI) / 180
  const a = chroma * Math.cos(radians)
  const b = chroma * Math.sin(radians)
  const ll = (l + 0.3963377774 * a + 0.2158037573 * b) ** 3
  const mm = (l - 0.1055613458 * a - 0.0638541728 * b) ** 3
  const ss = (l - 0.0894841775 * a - 1.291485548 * b) ** 3
  const toSrgb = (linear) =>
    Math.max(
      0,
      Math.min(1, linear <= 0.0031308 ? linear * 12.92 : 1.055 * linear ** (1 / 2.4) - 0.055),
    )
  return {
    colorSpace: 'srgb',
    alpha: colour.alpha,
    components: [
      toSrgb(4.0767416621 * ll - 3.3077115913 * mm + 0.2309699292 * ss),
      toSrgb(-1.2684380046 * ll + 2.6097574011 * mm - 0.3413193965 * ss),
      toSrgb(-0.0041960863 * ll - 0.7034186147 * mm + 1.707614701 * ss),
    ],
  }
}

// Premultiplied interpolation, as CSS color-mix() computes it: mixing an
// opaque colour toward transparent keeps its hue and scales its alpha,
// instead of darkening it. Opaque-to-opaque mixes are identical either way.
function mix(a, b, t) {
  const x = oklchToSrgb(a)
  const y = oklchToSrgb(b)
  const alpha = x.alpha + (y.alpha - x.alpha) * t
  if (alpha === 0) return { colorSpace: 'srgb', alpha: 0, components: [0, 0, 0] }
  return {
    colorSpace: 'srgb',
    alpha,
    components: x.components.map(
      (n, i) => (n * x.alpha * (1 - t) + y.components[i] * y.alpha * t) / alpha,
    ),
  }
}

function luminance(colour) {
  const linear = oklchToSrgb(colour).components.map((n) =>
    n <= 0.04045 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4,
  )
  return linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722
}

export function contrastRatio(foreground, background) {
  const [lighter, darker] = [luminance(foreground), luminance(background)].toSorted((a, b) => b - a)
  return (lighter + 0.05) / (darker + 0.05)
}

function anchors(consumers, mode) {
  const white = colourAt(consumers, mode, ANCHOR_WHITE)
  const black = colourAt(consumers, mode, ANCHOR_BLACK)
  for (const [name, colour, level] of [
    [ANCHOR_WHITE, white, 1],
    [ANCHOR_BLACK, black, 0],
  ]) {
    if (
      colour.colorSpace !== 'srgb' ||
      colour.alpha !== 1 ||
      colour.components.some((n) => n !== level)
    ) {
      throw new Error(`ANSI anchor is not pure: ${name} in ${mode}`)
    }
  }
  return { white, black }
}

// The terminal palette for one mode: chrome from the surface roles, hues
// from the semantic and syntax roles, cyan and the brights mixed from them
// by the fixed ratios above. black/white are the darker/lighter of surface
// and text, the terminal convention (xterm.js's own default black sits
// inside its default background the same way); their legibility is proven
// crosswise, not against the terminal background.
export function ansiTheme(consumers, mode) {
  const { white, black } = anchors(consumers, mode)
  const at = (name) => resolvedColour(consumers, mode, name)
  const surface = at('colour.surface')
  const text = at('colour.text')
  const [blackBase, whiteBase] = [surface, text].toSorted((a, b) => luminance(a) - luminance(b))
  const info = at('colour.info')
  const success = at('colour.success')
  const cyan = mix(info, success, CYAN_MIX)
  const bright = (colour) => mix(colour, white, BRIGHT_MIX)
  const hues = Object.fromEntries(Object.entries(ANSI_HUES).map(([hue, token]) => [hue, at(token)]))
  return {
    foreground: text,
    background: surface,
    cursor: at('colour.cursor'),
    cursorAccent: surface,
    selectionBackground: at('colour.selection'),
    selectionForeground: at('colour.on-selection'),
    selectionInactiveBackground: at('colour.hover'),
    overviewRulerBorder: at('colour.border'),
    black: blackBase,
    red: hues.red,
    green: hues.green,
    yellow: hues.yellow,
    blue: hues.blue,
    magenta: hues.magenta,
    cyan,
    white: whiteBase,
    brightBlack: at(BRIGHT_BLACK_TOKEN),
    brightRed: bright(hues.red),
    brightGreen: bright(hues.green),
    brightYellow: bright(hues.yellow),
    brightBlue: bright(hues.blue),
    brightMagenta: bright(hues.magenta),
    brightCyan: bright(cyan),
    brightWhite: bright(whiteBase),
    anchorBlack: black,
  }
}

// The editor roles ED's CodeMirror theme reads (custom properties), resolved
// per mode for canvas contexts and cross-checks.
const CM_ROLES = {
  text: 'colour.text',
  editorSurface: 'colour.editor-surface',
  muted: 'colour.muted',
  border: 'colour.border',
  hover: 'colour.hover',
  selection: 'colour.selection',
  surface: 'colour.surface',
  focus: 'colour.focus',
  syntaxKeyword: 'colour.syntax-keyword',
  syntaxString: 'colour.syntax-string',
  syntaxNumber: 'colour.syntax-number',
  syntaxFunction: 'colour.syntax-function',
  danger: 'colour.danger',
}

export const CM_HIGHLIGHT = [
  { tags: ['keyword', 'operatorKeyword', 'modifier', 'controlKeyword'], role: 'syntaxKeyword' },
  { tags: ['string', 'special(string)', 'regexp'], role: 'syntaxString' },
  { tags: ['number', 'bool', 'null', 'atom'], role: 'syntaxNumber' },
  {
    tags: ['function(variableName)', 'function(propertyName)', 'typeName', 'className'],
    role: 'syntaxFunction',
  },
  {
    tags: ['comment', 'lineComment', 'blockComment', 'docComment'],
    role: 'muted',
    fontStyle: 'italic',
  },
  { tags: ['invalid'], role: 'danger' },
]

export function cmTheme(consumers, mode) {
  return Object.fromEntries(
    Object.entries(CM_ROLES).map(([role, token]) => [
      role,
      emitHex(resolvedColour(consumers, mode, token)),
    ]),
  )
}

// The appearance contract, mirrored in the Rust crate and the QML theme: a
// concrete override wins; otherwise the portal's colour scheme picks light
// or dark (no preference, unknown and unreadable values fall back to dark,
// as M114's unthemed root does) and its contrast flag picks the
// high-contrast variant. Unknown override strings fall back to the portal.
export function resolveAppearance(scheme, contrast, override) {
  if (override !== 'system' && APPEARANCE_OVERRIDES.includes(override)) return override
  const isLight = scheme === PORTAL_SCHEME.preferLight
  const isHigh = contrast === PORTAL_CONTRAST.high
  if (isLight) return isHigh ? 'hc-light' : 'light'
  return isHigh ? 'hc-dark' : 'dark'
}

// Fully resolved CSS values: every alias is its literal, VS Code fallbacks
// take their Muse branch (the desktop has no VS Code host), and colour-mix
// formulas are computed. Anything else that still computes at render time
// (today only the viewport-relative column inset) keeps its shape with
// literals substituted. An unknown formula fails loudly: a new computed
// token needs a conscious mapping here, never a silent var chain.
const PLAIN_MS_VAR = /var\(\s*(--ms-[a-z][a-z\d-]*)\s*\)/g
const MS_FALLBACK_VAR = /var\(\s*(--ms-[a-z][a-z\d-]*)\s*,\s*[^()]*?\)/g
const VSCODE_FALLBACK_VAR = /var\(\s*--vscode-[a-zA-Z][a-zA-Z\d-]*\s*,\s*([^()]*?)\)/g
const INNERMOST_MIX = /color-mix\(\s*in srgb\s*,\s*([^(),]+?)\s+([\d.]+)%\s*,\s*([^(),]+?)\s*\)/g
const SUBSTITUTION_ROUNDS = 10

function literalColour(text) {
  const cleaned = text.trim()
  if (cleaned === 'transparent') return { colorSpace: 'srgb', components: [0, 0, 0], alpha: 0 }
  const literal = /^#([\da-f]{6}|[\da-f]{8})$/i.exec(cleaned)
  if (literal === null) throw new Error(`Desktop colour is not a hex literal: ${text}`)
  const bytes = literal[1].match(/[\da-f]{2}/gi).map((b) => Number.parseInt(b, 16) / 255)
  return { colorSpace: 'srgb', components: bytes.slice(0, 3), alpha: bytes[3] ?? 1 }
}

function variableToken(consumers, mode, variable) {
  const entries = Object.entries(consumers.modes[mode])
  for (const [name, entry] of entries) {
    if (entry.variable === variable) return name
  }
  throw new Error(`Unknown CSS variable: ${variable}`)
}

export function resolveCss(consumers, mode, name, seen = []) {
  if (seen.includes(name)) throw new Error(`Cyclic CSS reference: ${[...seen, name].join(' -> ')}`)
  const next = [...seen, name]
  const entry = entryAt(consumers, mode, name)
  let css = entry.css
  for (let round = 0; round < SUBSTITUTION_ROUNDS; round += 1) {
    const before = css
    css = css
      .replaceAll(PLAIN_MS_VAR, (_, variable) =>
        resolveCss(consumers, mode, variableToken(consumers, mode, variable), next),
      )
      .replaceAll(MS_FALLBACK_VAR, (_, variable) =>
        resolveCss(consumers, mode, variableToken(consumers, mode, variable), next),
      )
      .replaceAll(VSCODE_FALLBACK_VAR, (_, fallback) => fallback.trim())
      .replaceAll(INNERMOST_MIX, (_, first, percent, second) =>
        hexOf(mix(literalColour(first), literalColour(second), 1 - Number(percent) / 100)),
      )
    if (css === before) break
  }
  if (css.includes('var(') || css.includes('color-mix('))
    throw new Error(`Unresolved CSS formula in ${name}: ${css}`)
  return css
}

// Hex emission for any resolved colour, converting the OKLCH status ramp.
export function emitHex(colour) {
  return hexOf(oklchToSrgb(colour))
}

// The effective colour: the DTCG value, except where the CSS is a computed
// formula (the boundary mix, the translucent scrim), where the formula is
// what every surface actually shows. All desktop emission reads through
// here, so QML, Rust, Lua and JSON carry identical values.
export function resolvedColour(consumers, mode, name) {
  const entry = entryAt(consumers, mode, name)
  if (entry.type !== 'color') throw new Error(`Not a colour token: ${name}`)
  return entry.css.includes('color-mix')
    ? literalColour(resolveCss(consumers, mode, name))
    : colourAt(consumers, mode, name)
}

